import AccessorArray = require( '@stdlib/array/base/accessor' );
import cosineWave = require( './index' );


// TESTS //

// The function returns a numeric array...
{
	const x = new Float64Array( 10 );

	cosineWave( x.length, 4, 1.0, 0, x, 1 ); // $ExpectType Float64Array
	cosineWave( x.length, 4, 1.0, 0, new AccessorArray( x ), 1 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	cosineWave( '10', 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( true, 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( false, 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( null, 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( undefined, 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( [], 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( {}, 4, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( ( x: number ): number => x, 4, 1.0, 0, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float64Array( 10 );

	cosineWave( x.length, '10', 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, true, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, false, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, null, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, undefined, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, [], 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, {}, 1.0, 0, x, 1 ); // $ExpectError
	cosineWave( x.length, ( x: number ): number => x, 1.0, 0, x, 1 ); // $ExpectError
}

