	cosineWave( x.length, 4, 1.0, 0, true, 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, false, 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, null, 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, undefined, 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, [ '1' ], 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, {}, 1 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, ( x: number ): number => x, 1 ); // $ExpectError
