// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );

	cosineWave(); // $ExpectError
	cosineWave( x.length ); // $ExpectError
	cosineWave( x.length, 4 ); // $ExpectError
	cosineWave( x.length, 4, 1.0 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0 ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, x ); // $ExpectError
	cosineWave( x.length, 4, 1.0, 0, x, 1, 2 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a numeric array...
{
	const x = new Float64Array( 10 );

	cosineWave.ndarray( x.length, 4, 1.0, 0, x, 1, 0 ); // $ExpectType Float64Array
	cosineWave.ndarray( x.length, 4, 1.0, 0, new AccessorArray( x ), 1, 0 ); // $ExpectType AccessorArray<number>
}

